import org.graalvm.nativeimage.hosted.Feature;
public class ReachOnly implements Feature {
    public void beforeAnalysis(BeforeAnalysisAccess access) {
        Class<?> c=access.findClassByName("com.oracle.svm.interpreter.InterpreterForeignFunctionsSupportImpl");
        if (c==null) throw new AssertionError("singleton implementation unavailable");
        access.registerAsUsed(c);
        System.out.println("PROBE registered foreign implementation as used, without instantiation");
    }
}

