import java.lang.foreign.*;
import java.lang.invoke.*;
public class ForeignRoundtrip {
    public static long twice(long value) { return value * 2; }
    public static void main(String[] args) throws Throwable {
        Linker linker=Linker.nativeLinker();
        FunctionDescriptor descriptor=FunctionDescriptor.of(ValueLayout.JAVA_LONG,ValueLayout.JAVA_LONG);
        MethodHandle target=MethodHandles.lookup().findStatic(ForeignRoundtrip.class,"twice",MethodType.methodType(long.class,long.class));
        try (Arena arena=Arena.ofConfined()) {
            MemorySegment callback=linker.upcallStub(target,descriptor,arena);
            MethodHandle downcall=linker.downcallHandle(callback,descriptor);
            long result=(long)downcall.invokeExact(21L);
            if (result!=42) throw new AssertionError(result);
            System.out.println("runtime foreign roundtrip="+result);
        }
    }
}

